arguments.old_str:
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<IUserService, UserService>();
builder.Services.AddSingleton<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));
builder.Services.AddHttpClient("api")
    .ConfigureHttpMessageHandlerBuilder(b =>
    {
        ((HttpClientHandler)b.PrimaryHandler).UseCookies = false;
    });
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
});
var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

arguments.new_str:
var builder = WebApplication.CreateBuilder(args);

// Fix #2: Scoped IUserService was captured by singleton CacheService.
// .NET 9 enables ValidateScopes in development, which catches this.
// Change CacheService to scoped so it doesn't outlive its dependency.
builder.Services.AddScoped<IUserService, UserService>();
builder.Services.AddScoped<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));

// Fix #1: .NET 9 HttpClientFactory uses SocketsHttpHandler by default.
// Casting to HttpClientHandler throws InvalidCastException.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler { UseCookies = false });

// Fix #4: .NET 9 redacts all header values in Trace-level HttpClient logs.
// Allowlist non-sensitive headers needed for debugging.
builder.Services.ConfigureHttpClientDefaults(b =>
    b.RedactLoggedHeaders(h =>
        h != "X-Request-Id" && h != "X-Forwarded-For" && h != "X-Forwarded-Proto"));

// Fix #3: .NET 9 Forwarded Headers middleware ignores headers from unknown proxies.
// Configure KnownNetworks to trust your reverse proxy.
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
    options.KnownNetworks.Clear();
    options.KnownProxies.Clear();
    // TODO: Replace with your actual proxy addresses/networks for production safety:
    // options.KnownProxies.Add(IPAddress.Parse("10.0.0.1"));
    // For now, trust loopback (common for local reverse proxy / sidecar):
    options.ForwardLimit = null;
});

var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

